window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5ceea2a87bf7d9bf"]={"versions": [{"id": "FIG-5ceea2a87bf7d9bf", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition im Kontext der AUTOSAR E2E-Bibliothek (<code>E2E_StateMachineTypes</code>). Das Diagramm spezifiziert die Datenstrukturen zur Repräsentation des dynamischen Zustands der End-to-End-Zustandsmaschine bei der Prüfung von Datenströmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Datentypen im Namensraum <code>E2E::E2E_StateMachineTypes::</code>:</p>\n<ul class=\"fig-list\">\n<li>Struktur <code>E2E_SMCheckStateType</code> («structure»):</li>\n<li><code>ErrorCount</code>: <code>uint8</code> – Zähler für fehlerhafte Kommunikationszyklen.</li>\n<li><code>OkCount</code>: <code>uint8</code> – Zähler für fehlerfreie Zyklen.</li>\n<li><code>ProfileStatusWindow</code>: <code>uint8*</code> – Zeiger auf das Schiebefenster zur Historie der Profilstatuswerte.</li>\n<li><code>SMState</code>: <code>E2E_SMStateType</code> – Aktueller Zustand der E2E-Zustandsmaschine.</li>\n<li><code>WindowTopIndex</code>: <code>uint8</code> – Index auf den aktuellen Eintrag im Schiebefenster.</li>\n<li>Zustandstyp <code>E2E_SMStateType</code> («type») mit folgenden Werten:</li>\n<li><code>E2E_SM_DEINIT = 0x01</code></li>\n<li><code>E2E_SM_INIT = 0x03</code></li>\n<li><code>E2E_SM_INVALID = 0x04</code></li>\n<li><code>E2E_SM_NODATA = 0x02</code></li>\n<li><code>E2E_SM_VALID = 0x00</code></li>\n<li><code>reserved = 0x07, 0x0F</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne Verhaltens- oder Sequenzmodellierung. Die Instanzen von <code>E2E_SMCheckStateType</code> halten den Ausführungszustand eines Prüfers (<code>E2E_SMCheck</code>), der über aufeinanderfolgende Aufrufe hinweg aktualisiert wird, um den Übergang zwischen den in <code>E2E_SMStateType</code> definierten Zuständen zu steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C-Typdefinitionen für Software-Komponenten und E2E-Bibliotheksanwender. Speicher für <code>ProfileStatusWindow</code> muss vorab als Byte-Array allokiert und bereitgestellt werden. Werte für <code>E2E_SMStateType</code> sind explizit mit Hexadezimalwerten kodiert; ungenutzte Wertebereiche (<code>0x07, 0x0F</code>) sind reserviert.</p>"}, {"id": "FIG-5525fea5ebb804cf", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition im Kontext der AUTOSAR E2E-Bibliothek (<code>E2E_StateMachineTypes</code>). Das Diagramm spezifiziert die Datenstrukturen zur Repräsentation des dynamischen Zustands der End-to-End-Zustandsmaschine bei der Prüfung von Datenströmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Datentypen im Namensraum <code>E2E_StateMachineTypes::</code>:</p>\n<ul class=\"fig-list\">\n<li>Struktur <code>E2E_SMCheckStateType</code> («structure»):</li>\n<li><code>ErrorCount: uint8</code> – Zähler für fehlerhafte Kommunikationszyklen.</li>\n<li><code>OkCount: uint8</code> – Zähler für fehlerfreie Zyklen.</li>\n<li><code>ProfileStatusWindow: uint8*</code> – Zeiger auf das Schiebefenster zur Historie der Profilstatuswerte.</li>\n<li><code>SMState: E2E_SMStateType</code> – Aktueller Zustand der E2E-Zustandsmaschine.</li>\n<li><code>WindowTopIndex: uint8</code> – Index auf den aktuellen Eintrag im Schiebefenster.</li>\n<li>Zustandstyp <code>E2E_SMStateType</code> («type») mit folgenden Werten:</li>\n<li><code>E2E_SM_DEINIT = 0x01</code></li>\n<li><code>E2E_SM_INIT = 0x03</code></li>\n<li><code>E2E_SM_INVALID = 0x04</code></li>\n<li><code>E2E_SM_NODATA = 0x02</code></li>\n<li><code>E2E_SM_VALID = 0x00</code></li>\n<li><code>reserved = 0x07, 0x0F</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne Verhaltens- oder Sequenzmodellierung. Die Instanzen von <code>E2E_SMCheckStateType</code> halten den Ausführungszustand eines Prüfers (<code>E2E_SMCheck</code>), der über aufeinanderfolgende Aufrufe hinweg aktualisiert wird, um den Übergang zwischen den in <code>E2E_SMStateType</code> definierten Zuständen zu steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C-Typdefinitionen für Software-Komponenten und E2E-Bibliotheksanwender. Speicher für <code>ProfileStatusWindow</code> muss vorab als Byte-Array allokiert und bereitgestellt werden. Werte für <code>E2E_SMStateType</code> sind explizit mit Hexadezimalwerten kodiert; ungenutzte Wertebereiche (<code>0x07, 0x0F</code>) sind reserviert.</p>"}, {"id": "FIG-1dfc4d90870a0789", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition im Kontext der AUTOSAR E2E-Bibliothek (<code>E2E_StateMachineTypes</code>). Das Diagramm spezifiziert die Datenstrukturen zur Repräsentation des dynamischen Zustands der End-to-End-Zustandsmaschine bei der Prüfung von Datenströmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Datentypen im Namensraum <code>E2E_StateMachineTypes::</code>:</p>\n<ul class=\"fig-list\">\n<li>Struktur <code>E2E_SMCheckStateType</code> («structure»):</li>\n<li><code>ErrorCount: uint8</code> – Zähler für fehlerhafte Kommunikationszyklen.</li>\n<li><code>OkCount: uint8</code> – Zähler für fehlerfreie Zyklen.</li>\n<li><code>ProfileStatusWindow: uint8*</code> – Zeiger auf das Schiebefenster zur Historie der Profilstatuswerte.</li>\n<li><code>SMState: E2E_SMStateType</code> – Aktueller Zustand der E2E-Zustandsmaschine.</li>\n<li><code>WindowTopIndex: uint8</code> – Index auf den aktuellen Eintrag im Schiebefenster.</li>\n<li>Aufzählungstyp <code>E2E_SMStateType</code> («enumeration») unter dem Bereich <code>Attributes</code>:</li>\n<li><code>E2E_SM_VALID = 0x00</code></li>\n<li><code>E2E_SM_DEINIT = 0x01</code></li>\n<li><code>E2E_SM_NODATA = 0x02</code></li>\n<li><code>E2E_SM_INIT = 0x03</code></li>\n<li><code>E2E_SM_INVALID = 0x04</code></li>\n<li><code>reserved = 0x07, 0x0F</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne Verhaltens- oder Sequenzmodellierung. Die Instanzen von <code>E2E_SMCheckStateType</code> halten den Ausführungszustand eines Prüfers (<code>E2E_SMCheck</code>), der über aufeinanderfolgende Aufrufe hinweg aktualisiert wird, um den Übergang zwischen den in <code>E2E_SMStateType</code> definierten Zuständen zu steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C-Typdefinitionen für Software-Komponenten und E2E-Bibliotheksanwender. <code>E2E_SMStateType</code> ist als Enumeration typisiert; die Werte sind numerisch aufsteigend beginnend bei <code>0x00</code> geordnet, mit reservierten Werten <code>0x07, 0x0F</code>. Speicher für <code>ProfileStatusWindow</code> muss vorab als Byte-Array allokiert und bereitgestellt werden.</p>"}], "trans": [{"from": "FIG-5ceea2a87bf7d9bf", "to": "FIG-5525fea5ebb804cf", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Package-Präfix / Namensraum: In den Kopfzeilen beider Datentypen (<code>E2E_SMCheckStateType</code> und <code>E2E_SMStateType</code>) wurde das übergeordnete Namensraumpräfix <code>E2E::</code> entfernt (<code>«structure» E2E_StateMachineTypes::</code> bzw. <code>«type» E2E_StateMachineTypes::</code>).</li>\n<li>Formatierung: Vor den Doppelpunkten der Typannotationen in <code>E2E_SMCheckStateType</code> wurden Leerzeichen entfernt (<code>ErrorCount: uint8</code>, <code>OkCount: uint8</code>, etc.).</li>\n</ul>"}, {"from": "FIG-5525fea5ebb804cf", "to": "FIG-1dfc4d90870a0789", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Stereotyp: <code>E2E_SMStateType</code> wurde von <code>«type»</code> auf <code>«enumeration»</code> umgestellt.</li>\n<li>Aufzählungsabschnitt: In <code>E2E_SMStateType</code> wurde der Bereichskopf <code>Attributes</code> eingefügt.</li>\n<li>Aufzählungswerte / Reihenfolge: Die Literale von <code>E2E_SMStateType</code> wurden neu geordnet (<code>E2E_SM_VALID = 0x00</code> steht nun an erster Stelle, gefolgt von <code>E2E_SM_DEINIT = 0x01</code>, <code>E2E_SM_NODATA = 0x02</code>, <code>E2E_SM_INIT = 0x03</code>, <code>E2E_SM_INVALID = 0x04</code> und <code>reserved = 0x07, 0x0F</code>).</li>\n</ul>"}]};
